from __future__ import annotations

from pydantic import Field
from typing_extensions import NotRequired, TypedDict

from ..core import UNSET, Optional, SdkBaseModel


class NonprofitCause(SdkBaseModel):
    banner_url: str = Field(alias="bannerUrl")
    """The URL to the banner of the cause."""

    description: str
    """The description of the cause."""

    id: Optional[str] = UNSET
    """The unique identifier of the cause. This value is generated by Adyen."""

    locales: list[str]
    """The locales that the cause supports, in `IETF BCP 47 <https://en.wikipedia.org/wiki/IETF_language_tag>`__
    format."""

    name: str
    """The name of the cause."""


class NonprofitCauseDict(TypedDict):
    banner_url: str
    description: str
    id: NotRequired[str]
    locales: list[str]
    name: str
